import json
import re

def validate_data(data, physical_limits):
    """
    Validates atmospheric data against a schema and physical limits.

    Args:
        data (dict): The atmospheric data to validate.
        physical_limits (dict): Dictionary containing physical limits.

    Returns:
        list: A list of error messages.  Empty list if no errors.
    """
    errors = []

    # Validate against JSON Schema
    try:
        json.loads(json.dumps(data))  # Basic schema validation
    except Exception as e:
        errors.append(f"Schema validation error: {e}")
        return errors

    # Validate physical limits
    if data['wind_speed_ms'] is not None and data['wind_speed_ms'] > physical_limits['max_wind_speed_ms']:
        errors.append(f"Wind speed exceeds limit: {data['wind_speed_ms']} > {physical_limits['max_wind_speed_ms']} m/s")
    if data['pressure_hpa'] is not None and data['pressure_hpa'] < physical_limits['min_pressure_hpa']:
        errors.append(f"Pressure is below limit: {data['pressure_hpa']} < {physical_limits['min_pressure_hpa']} hPa")
    if data['pressure_hpa'] is not None and data['pressure_hpa'] > physical_limits['max_pressure_hpa']:
        errors.append(f"Pressure is above limit: {data['pressure_hpa']} > {physical_limits['max_pressure_hpa']} hPa")

    return errors
